<template><q-dialog v-model="visible"><q-card class="form-card"><q-card-section class="row justify-between items-center"><div class="text-h6 text-green-9 text-weight-bold">Editar lote</div><q-btn flat round icon="close" v-close-popup/></q-card-section><q-card-section><q-input v-model="form.producto" outlined label="Producto" readonly class="q-mb-md"/><div class="row q-col-gutter-md"><q-input v-model="form.codigoLote" outlined label="Código de lote" class="col-12 col-sm-6"/><q-input v-model="form.fechaFabricacion" outlined type="date" label="Fecha fabricación" class="col-12 col-sm-6"/><q-input v-model="form.fechaVencimiento" outlined type="date" label="Fecha vencimiento" class="col-12 col-sm-6"/><q-input v-model="form.stock" outlined label="Stock actual" disable class="col-12 col-sm-6"/><q-input v-model="form.observacion" outlined label="Observación" class="col-12"/></div></q-card-section><q-card-actions align="right"><q-btn flat label="Cancelar" v-close-popup/><q-btn unelevated color="green-8" label="Guardar" :loading="guardando" @click="guardar"/></q-card-actions></q-card></q-dialog></template>
<script setup>import{computed,reactive,ref,watch}from'vue';import{useQuasar}from'quasar';import{actualizarLote}from'../../api/lotes/lotes';const $q=useQuasar();const props=defineProps({modelValue:Boolean,lote:Object});const emit=defineEmits(['update:modelValue','guardar']);const visible=computed({get:()=>props.modelValue,set:v=>emit('update:modelValue',v)});const guardando=ref(false);const form=reactive({producto:'',codigoLote:'',fechaFabricacion:'',fechaVencimiento:'',stock:0,observacion:''});watch(()=>props.lote,v=>{if(v)Object.assign(form,{...v,stock:v.cantidad??v.stock??0})},{immediate:true});async function guardar(){if(!props.lote?.idLote)return $q.notify({type:'negative',message:'No se encontró el lote'});guardando.value=true;try{const r=await actualizarLote(props.lote.idLote,{codigoLote:form.codigoLote,fechaFabricacion:form.fechaFabricacion||null,fechaVencimiento:form.fechaVencimiento||null,observacion:form.observacion||null});emit('guardar',r);$q.notify({type:'positive',message:'Lote guardado correctamente'});visible.value=false}catch(e){$q.notify({type:'negative',message:e.response?.data?.message||'No se pudo guardar el lote'})}finally{guardando.value=false}}</script><style scoped>.form-card{width:700px;max-width:95vw;border-radius:18px}</style>
